// Run against the local Vite dev server, using fixtures generated by the companion Python script.
import assert from "node:assert/strict";
import fs from "node:fs/promises";
const { chromium, devices } = await import(
  process.env.PLAYWRIGHT_MODULE || "playwright"
);
const root = process.argv[2] || "/private/tmp/pdf-to-powerpoint-qa";
const browser = await chromium.launch({
  headless: true,
  ...(process.env.CHROME_PATH
    ? { executablePath: process.env.CHROME_PATH }
    : {}),
});
const results = [];
async function load(page, file) {
  await page.evaluate(() => {
    document.getElementById("qa-file")?.remove();
    const input = document.createElement("input");
    input.type = "file";
    input.id = "qa-file";
    document.body.append(input);
  });
  await page.setInputFiles("#qa-file", `${root}/${file}`);
}
try {
  const context = await browser.newContext();
  const page = await context.newPage();
  await page.goto("http://127.0.0.1:5197/pdf-to-powerpoint", {
    waitUntil: "domcontentloaded",
    timeout: 90000,
  });
  await page.waitForSelector("#powerpoint-upload", { state: "attached" });
  for (const file of [
    "invalid.pdf",
    "empty.pdf",
    "damaged.pdf",
    "encrypted.pdf",
  ]) {
    await load(page, file);
    const result = await page.evaluate(async () => {
      const { convertPdfToPowerPoint } = await import(
        "/src/utils/pdfToPowerPoint/convert.ts"
      );
      try {
        await convertPdfToPowerPoint(
          document.querySelector("#qa-file").files[0],
          new AbortController().signal,
          () => {},
        );
        return { failed: false };
      } catch (e) {
        return { failed: true, error: e.message };
      }
    });
    assert.equal(result.failed, true);
    results.push({ file, ...result });
    console.log(file, result.error);
  }
  await load(page, "many.pdf");
  const many = await page.evaluate(async () => {
    const { convertPdfToPowerPoint } = await import(
      "/src/utils/pdfToPowerPoint/convert.ts"
    );
    const file = document.querySelector("#qa-file").files[0];
    const r = await convertPdfToPowerPoint(
      file,
      new AbortController().signal,
      () => {},
    );
    return {
      pages: r.report.pages.length,
      bytes: r.blob.size,
      ms: r.report.elapsedMs,
    };
  });
  assert.equal(many.pages, 75);
  results.push({ many });
  console.log("Many pages", many);
  const cancel = await page.evaluate(async () => {
    const { convertPdfToPowerPoint } = await import(
      "/src/utils/pdfToPowerPoint/convert.ts"
    );
    const run = new AbortController();
    try {
      await convertPdfToPowerPoint(
        document.querySelector("#qa-file").files[0],
        run.signal,
        () => run.abort(),
      );
      return false;
    } catch (e) {
      return e.name === "AbortError";
    }
  });
  assert.equal(cancel, true);
  results.push({ cancel });
  // Real component and shared credit gate. This is a fresh disposable browser profile.
  await page.setInputFiles("#powerpoint-upload", `${root}/torture.pdf`);
  await page
    .getByRole("button", { name: "Convert to PowerPoint", exact: true })
    .waitFor();
  await page.waitForFunction(
    () =>
      !Array.from(document.querySelectorAll("button")).find(
        (b) => b.textContent === "Convert to PowerPoint",
      )?.disabled,
  );
  const credits = () =>
    page.evaluate(async () => {
      const { getDailyUsage } = await import("/src/utils/usageTracker.ts");
      return getDailyUsage().remaining;
    });
  const before = await credits();
  await page.getByLabel("Pages", { exact: true }).fill("1");
  await page
    .getByRole("button", { name: "Convert to PowerPoint", exact: true })
    .click();
  await page
    .getByRole("link", { name: "Download PowerPoint", exact: true })
    .waitFor({ timeout: 90000 });
  const after = await credits();
  assert.equal(after, before - 1);
  const downloadPromise = page.waitForEvent("download");
  await page
    .getByRole("link", { name: "Download PowerPoint", exact: true })
    .click();
  const download = await downloadPromise;
  await download.saveAs(`${root}/ui.pptx`);
  assert.equal(await credits(), after);
  await page
    .getByRole("button", { name: "Change options", exact: true })
    .click();
  await page.getByLabel("Pages", { exact: true }).fill("9999");
  await page
    .getByRole("button", { name: "Convert to PowerPoint", exact: true })
    .click();
  await page
    .getByRole("alert")
    .filter({ hasText: "Choose page numbers" })
    .waitFor();
  assert.equal(await credits(), after);
  await page.getByLabel("Pages", { exact: true }).fill("1-24");
  await page
    .getByRole("button", { name: "Convert to PowerPoint", exact: true })
    .click();
  await page
    .getByRole("button", { name: "Cancel conversion", exact: true })
    .click();
  await page
    .getByRole("status")
    .filter({ hasText: "Conversion cancelled" })
    .waitFor();
  assert.equal(await credits(), after);
  await page.screenshot({ path: `${root}/ui-desktop.png`, fullPage: true });
  results.push({
    credits: {
      before,
      after,
      failure: await credits(),
      downloadCharged: false,
      cancelCharged: false,
    },
  });
  // Mobile-sized Chrome is an emulation check, not a physical-device claim.
  const mobile = await browser.newContext({ ...devices["Pixel 7"] });
  const phone = await mobile.newPage();
  await phone.goto("http://127.0.0.1:5197/pdf-to-powerpoint", {
    waitUntil: "domcontentloaded",
    timeout: 90000,
  });
  await phone.waitForSelector("#powerpoint-upload", { state: "attached" });
  await load(phone, "torture.pdf");
  const mobileResult = await phone.evaluate(async () => {
    const { convertPdfToPowerPoint } = await import(
      "/src/utils/pdfToPowerPoint/convert.ts"
    );
    const r = await convertPdfToPowerPoint(
      document.querySelector("#qa-file").files[0],
      new AbortController().signal,
      () => {},
      { pages: "1-5" },
    );
    return {
      pages: r.report.pages.length,
      maxPixels: Math.max(...r.report.pages.map((p) => p.renderPixels)),
      ms: r.report.elapsedMs,
    };
  });
  assert.equal(mobileResult.pages, 5);
  assert.ok(mobileResult.maxPixels < 3_005_000);
  results.push({ mobileEmulation: mobileResult });
  await phone.screenshot({ path: `${root}/ui-mobile.png`, fullPage: true });
  await fs.writeFile(
    `${root}/integration.json`,
    JSON.stringify(results, null, 2),
  );
  console.log(JSON.stringify(results));
} finally {
  await browser.close();
}
